test('Test All checks each node destination without changing storage',async()=>{
 const calls=[];const page=await mounted('pages/BackupDestinations.tsx',{},async(p,init)=>{calls.push({p,init});return destinationApi(p)});try{await page.click(button(page.container,'Test All'));assert.equal(page.container.querySelectorAll('.destination-checks>div').length,3);assert.deepEqual(calls.filter(c=>c.p.includes('history=0')).map(c=>c.p).sort(),['/proxmox/storage/n1/local?history=0','/proxmox/storage/n1/shared?history=0','/proxmox/storage/n2/shared?history=0']);assert.ok(!calls.some(c=>['POST','PUT','DELETE'].includes(c.init?.method)));}finally{await page.close();}
});
test('adding a destination registers backup content through the storage API',async()=>{
 const writes=[];const page=await mounted('pages/BackupDestinations.tsx',{},async(p,init)=>{if(init?.method==='POST'){writes.push({p,body:JSON.parse(init.body)});return {}}return destinationApi(p)});try{await page.click(button(page.container,'Add Destination'));const form=page.container.querySelector('.modal form');form.querySelector('[name=storage]').value='new-backup';form.querySelector('[name=path]').value='/mnt/backup';await act(async()=>{form.dispatchEvent(new page.dom.window.Event('submit',{bubbles:true,cancelable:true}));await new Promise(r=>setTimeout(r,0));});assert.equal(writes[0].p,'/proxmox/storage');assert.equal(writes[0].body.content,'backup');assert.equal(writes[0].body.type,'dir');assert.equal(writes[0].body.storage,'new-backup');assert.ok(page.container.querySelector('[role=status]').textContent.includes('registered'));}finally{await page.close();}
});
