test('backup report exports include only filtered tasks and coverage metadata',async()=>{
 let blob;const originalCreate=URL.createObjectURL,originalRevoke=URL.revokeObjectURL;URL.createObjectURL=value=>{blob=value;return 'blob:report-fixture'};URL.revokeObjectURL=()=>{};const page=await mounted('pages/BackupReports.tsx',{hours:'168',setHours(){}},reportApi);page.dom.window.HTMLAnchorElement.prototype.click=function(){};try{const outcome=page.container.querySelector('[aria-label="Report outcome"]');await act(async()=>{outcome.value='Failed';outcome.dispatchEvent(new page.dom.window.Event('change',{bubbles:true}));});await page.click(button(page.container,'Export Report'));const data=JSON.parse(await blob.text());assert.equal(data.hours,168);assert.equal(data.filters.status,'Failed');assert.deepEqual(data.tasks.map(t=>t.upid),['report-fail']);assert.ok(data.coverage.scope.includes('Returned'));}finally{await page.close();URL.createObjectURL=originalCreate;URL.revokeObjectURL=originalRevoke;}
});
test('backup report failures use unknown statistics and recover through retry',async()=>{
 let fail=true;const page=await mounted('pages/BackupReports.tsx',{hours:'24',setHours(){}},async p=>{if(p.startsWith('/proxmox/tasks')&&fail)throw Error('Failed to fetch');return reportApi(p)});try{assert.ok(page.container.querySelector('[role=alert]').textContent.includes('Unable to load backup reports'));assert.equal(button(page.container,'Export Report').disabled,true);assert.ok([...page.container.querySelectorAll('.report-stats strong')].every(c=>c.textContent==='Unknown'));fail=false;await page.click(button(page.container,'Retry'));assert.equal(page.container.querySelector('[role=alert]'),null);assert.equal(button(page.container,'Export Report').disabled,false);}finally{await page.close();}
});
